/**
 * OmniChat Standalone Production Visitor Widget v3.5.0
 * Zero-Dependency, Pure Vanilla JS with Realtime SSE & Offline Recovery
 */
(function(window, document) {
  'use strict';

  var Config = {
    endpoint: '.',
    themeColor: '#007AFF',
    title: 'پشتیبانی آنلاین',
    subtitle: 'پاسخگویی سریع کارشناسان',
    welcomeMessage: 'سلام! وقتتون بخیر. چطور می‌تونیم کمکتون کنیم؟',
    position: 'bottom-left'
  };

  var EventBus = {
    events: {},
    on: function(event, cb) {
      if (!this.events[event]) this.events[event] = [];
      this.events[event].push(cb);
    },
    emit: function(event, data) {
      if (this.events[event]) {
        this.events[event].forEach(function(cb) { cb(data); });
      }
    }
  };

  function generateUUID() {
    return 'id_' + Math.random().toString(36).substring(2, 10) + Date.now().toString(36);
  }

  function formatTime(d) {
    var date = d ? new Date(d) : new Date();
    return date.getHours().toString().padStart(2, '0') + ':' + date.getMinutes().toString().padStart(2, '0');
  }

  function escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function linkify(text) {
    var urlPattern = /(\b(https?|ftp):\/\/[-A-Z0-9+&@#\/%?=~_|!:,.;]*[-A-Z0-9+&@#\/%=~_|])/gim;
    return text.replace(urlPattern, '<a href="$1" target="_blank" rel="noopener noreferrer" style="color:#007AFF;text-decoration:underline;">$1</a>');
  }

  var StorageManager = {
    getVisitorId: function() {
      var vid = localStorage.getItem('omnichat_visitor_id');
      if (!vid) {
        vid = 'vis_' + generateUUID();
        localStorage.setItem('omnichat_visitor_id', vid);
      }
      return vid;
    },
    getConversationId: function() {
      var cid = localStorage.getItem('omnichat_conv_id');
      if (!cid) {
        var vid = this.getVisitorId();
        cid = 'conv_' + vid.substring(4, 12) + '_' + Math.random().toString(36).substring(2, 6);
        localStorage.setItem('omnichat_conv_id', cid);
      }
      return cid;
    },
    getPendingMessages: function() {
      var raw = localStorage.getItem('omnichat_pending_msgs');
      return raw ? JSON.parse(raw) : [];
    },
    addPendingMessage: function(msg) {
      var queue = this.getPendingMessages();
      queue.push(msg);
      localStorage.setItem('omnichat_pending_msgs', JSON.stringify(queue));
    },
    removePendingMessage: function(clientId) {
      var queue = this.getPendingMessages().filter(function(m) { return m.clientMessageId !== clientId; });
      localStorage.setItem('omnichat_pending_msgs', JSON.stringify(queue));
    }
  };

  var WidgetApi = {
    fetchMessages: function() {
      var convId = StorageManager.getConversationId();
      return fetch(Config.endpoint + '/api.php?action=get_messages&conversation_id=' + encodeURIComponent(convId) + '&limit=50')
        .then(function(res) { return res.json(); })
        .then(function(data) { return data.status === 'success' ? data.messages : []; })
        .catch(function() { return []; });
    },
    sendMessage: function(params) {
      var convId = StorageManager.getConversationId();
      var visitorId = StorageManager.getVisitorId();

      return fetch(Config.endpoint + '/api.php?action=send_message', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          conversation_id: convId,
          visitor_id: visitorId,
          client_message_id: params.clientMessageId,
          sender: 'visitor',
          sender_name: params.senderName || 'کاربر مهمان',
          text: params.text,
          file_attachment: params.fileAttachment || null
        })
      }).then(function(res) { return res.json(); });
    },
    uploadFile: function(file) {
      var formData = new FormData();
      formData.append('file', file);
      return fetch(Config.endpoint + '/api.php?action=upload_file', {
        method: 'POST',
        body: formData
      }).then(function(res) { return res.json(); });
    },
    sendTyping: function() {
      var convId = StorageManager.getConversationId();
      fetch(Config.endpoint + '/api.php?action=set_typing', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ conversation_id: convId, sender: 'visitor', sender_name: 'کاربر مهمان' })
      }).catch(function() {});
    },
    pingVisitor: function() {
      var visitorId = StorageManager.getVisitorId();
      fetch(Config.endpoint + '/api.php?action=visitor_ping', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ visitor_id: visitorId, name: 'کاربر مهمان', current_page: window.location.pathname })
      }).catch(function() {});
    }
  };

  var SSEClient = {
    eventSource: null,
    lastEventId: 0,
    connect: function() {
      this.disconnect();
      var self = this;
      var convId = StorageManager.getConversationId();
      var url = Config.endpoint + '/stream.php?conversation_id=' + encodeURIComponent(convId) + '&last_id=' + this.lastEventId + '&role=visitor';

      if (typeof EventSource !== 'undefined') {
        try {
          this.eventSource = new EventSource(url);
          this.eventSource.addEventListener('message', function(e) {
            if (e.lastEventId) self.lastEventId = parseInt(e.lastEventId, 10);
            try {
              var msg = JSON.parse(e.data);
              if (msg.id && msg.id > self.lastEventId) self.lastEventId = msg.id;
              EventBus.emit('chat:message', msg);
            } catch (err) {}
          });
          this.eventSource.addEventListener('typing', function(e) {
            try { EventBus.emit('chat:typing', JSON.parse(e.data)); } catch (err) {}
          });
          this.eventSource.onerror = function() {
            self.handleReconnect();
          };
        } catch (e) {
          self.startPolling();
        }
      } else {
        self.startPolling();
      }
    },
    handleReconnect: function() {
      this.disconnect();
      var self = this;
      setTimeout(function() { self.connect(); }, 4000);
    },
    startPolling: function() {
      var self = this;
      if (this.pollTimer) return;
      this.pollTimer = setInterval(function() {
        var convId = StorageManager.getConversationId();
        fetch(Config.endpoint + '/api.php?action=poll_messages&conversation_id=' + encodeURIComponent(convId) + '&last_id=' + self.lastEventId)
          .then(function(res) { return res.json(); })
          .then(function(data) {
            if (data.status === 'success' && data.messages) {
              data.messages.forEach(function(msg) {
                if (msg.id > self.lastEventId) {
                  self.lastEventId = msg.id;
                  EventBus.emit('chat:message', msg);
                }
              });
            }
          });
      }, 5000);
    },
    disconnect: function() {
      if (this.eventSource) { this.eventSource.close(); this.eventSource = null; }
      if (this.pollTimer) { clearInterval(this.pollTimer); this.pollTimer = null; }
    }
  };

  function playChime() {
    try {
      var AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (!AudioContextClass) return;
      var ctx = new AudioContextClass();
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(587.33, ctx.currentTime);
      osc.frequency.setValueAtTime(880, ctx.currentTime + 0.08);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.35);
    } catch (e) {}
  }

  function WidgetUI() {
    this.isOpen = false;
    this.unreadCount = 0;
    this.init();
  }

  WidgetUI.prototype.init = function() {
    var self = this;
    if (document.getElementById('omnichat-widget-root')) return;

    var container = document.createElement('div');
    container.id = 'omnichat-widget-root';
    container.innerHTML = this.getHTML();
    document.body.appendChild(container);

    this.bindDOM();

    WidgetApi.fetchMessages().then(function(msgs) {
      self.renderMessages(msgs);
      if (msgs.length > 0) {
        var last = msgs[msgs.length - 1];
        if (last.id) SSEClient.lastEventId = last.id;
      }
    });

    SSEClient.connect();
    WidgetApi.pingVisitor();

    EventBus.on('chat:message', function(msg) {
      self.appendMessage(msg);
      if (!self.isOpen && msg.sender === 'operator') {
        self.unreadCount++;
        self.updateBadge();
        playChime();
      }
    });

    EventBus.on('chat:typing', function(data) {
      var el = document.getElementById('omnichat-typing');
      if (el) {
        if (data.isTyping) {
          el.textContent = (data.senderName || 'پشتیبان') + ' در حال نوشتن...';
          el.style.display = 'block';
        } else {
          el.style.display = 'none';
        }
      }
    });

    window.addEventListener('online', function() {
      SSEClient.connect();
    });
  };

  WidgetUI.prototype.getHTML = function() {
    var isLeft = Config.position === 'bottom-left';
    return '<style>' +
      '#omnichat-widget-root { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; direction: rtl; z-index: 999999; position: fixed; bottom: 24px; ' + (isLeft ? 'left:24px;' : 'right:24px;') + ' }' +
      '.omni-btn { width: 58px; height: 58px; border-radius: 29px; background: ' + Config.themeColor + '; color: #fff; border: none; box-shadow: 0 8px 24px rgba(0,122,255,0.35); cursor: pointer; display: flex; align-items: center; justify-content: center; position: relative; font-size: 24px; }' +
      '.omni-badge { position: absolute; top: -4px; right: -4px; background: #ff3b30; color: #fff; font-size: 11px; font-weight: 700; min-width: 20px; height: 20px; border-radius: 10px; display: none; align-items: center; justify-content: center; padding: 0 4px; border: 2px solid #fff; }' +
      '.omni-box { position: absolute; bottom: 74px; ' + (isLeft ? 'left: 0;' : 'right: 0;') + ' width: 370px; height: 540px; max-width: calc(100vw - 32px); max-height: calc(100vh - 100px); background: #fff; border-radius: 24px; box-shadow: 0 16px 48px rgba(0,0,0,0.18); display: none; flex-direction: column; overflow: hidden; }' +
      '.omni-box.open { display: flex; }' +
      '.omni-head { background: ' + Config.themeColor + '; color: #fff; padding: 16px 18px; display: flex; align-items: center; justify-content: space-between; }' +
      '.omni-head h4 { margin: 0; font-size: 15px; font-weight: 700; }' +
      '.omni-head p { margin: 2px 0 0; font-size: 11px; opacity: 0.85; }' +
      '.omni-close { background: rgba(255,255,255,0.2); border: none; color: #fff; width: 30px; height: 30px; border-radius: 15px; cursor: pointer; }' +
      '.omni-msgs { flex: 1; padding: 16px; overflow-y: auto; background: #f8fafc; display: flex; flex-direction: column; gap: 10px; }' +
      '.omni-bubble { max-width: 80%; padding: 10px 14px; border-radius: 18px; font-size: 13px; line-height: 1.5; word-break: break-word; }' +
      '.omni-bubble.visitor { align-self: flex-start; background: ' + Config.themeColor + '; color: #fff; border-bottom-right-radius: 4px; }' +
      '.omni-bubble.operator { align-self: flex-end; background: #fff; color: #1e293b; border-bottom-left-radius: 4px; box-shadow: 0 2px 6px rgba(0,0,0,0.04); }' +
      '.omni-time { font-size: 10px; opacity: 0.7; margin-top: 4px; text-align: left; direction: ltr; }' +
      '.omni-typing { font-size: 11px; color: #64748b; padding: 4px 16px; background: #f8fafc; display: none; }' +
      '.omni-bar { padding: 12px 14px; background: #fff; border-top: 1px solid #e2e8f0; display: flex; align-items: center; gap: 8px; }' +
      '.omni-bar textarea { flex: 1; border: 1px solid #e2e8f0; border-radius: 16px; padding: 8px 12px; font-size: 13px; outline: none; resize: none; height: 36px; font-family: inherit; }' +
      '.omni-sbtn, .omni-abtn { width: 36px; height: 36px; border-radius: 18px; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center; }' +
      '.omni-sbtn { background: ' + Config.themeColor + '; color: #fff; }' +
      '.omni-abtn { background: #f1f5f9; color: #64748b; }' +
      '</style>' +
      '<div class="omni-box" id="omnichat-window">' +
        '<div class="omni-head">' +
          '<div><h4>' + escapeHtml(Config.title) + '</h4><p>' + escapeHtml(Config.subtitle) + '</p></div>' +
          '<button type="button" class="omni-close" id="omnichat-close">✕</button>' +
        '</div>' +
        '<div class="omni-msgs" id="omnichat-msg-list"></div>' +
        '<div class="omni-typing" id="omnichat-typing"></div>' +
        '<div class="omni-bar">' +
          '<input type="file" id="omnichat-file" style="display:none;" />' +
          '<button type="button" class="omni-abtn" id="omnichat-attach">📎</button>' +
          '<textarea id="omnichat-input" placeholder="پیام خود را بنویسید..." rows="1"></textarea>' +
          '<button type="button" class="omni-sbtn" id="omnichat-send">➤</button>' +
        '</div>' +
      '</div>' +
      '<button type="button" class="omni-btn" id="omnichat-launcher">' +
        '💬<div class="omni-badge" id="omnichat-badge">0</div>' +
      '</button>';
  };

  WidgetUI.prototype.bindDOM = function() {
    var self = this;
    var launcher = document.getElementById('omnichat-launcher');
    var close = document.getElementById('omnichat-close');
    var send = document.getElementById('omnichat-send');
    var attach = document.getElementById('omnichat-attach');
    var fileInput = document.getElementById('omnichat-file');
    var input = document.getElementById('omnichat-input');

    launcher.addEventListener('click', function() { self.toggle(); });
    close.addEventListener('click', function() { self.close(); });

    send.addEventListener('click', function() { self.send(); });
    input.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        self.send();
      } else {
        WidgetApi.sendTyping();
      }
    });

    attach.addEventListener('click', function() { fileInput.click(); });
    fileInput.addEventListener('change', function() {
      if (fileInput.files && fileInput.files[0]) {
        WidgetApi.uploadFile(fileInput.files[0]).then(function(res) {
          if (res.status === 'success') {
            WidgetApi.sendMessage({
              text: '📎 فایل پیوست: ' + res.file.name,
              clientMessageId: generateUUID(),
              fileAttachment: res.file
            });
          }
        });
        fileInput.value = '';
      }
    });
  };

  WidgetUI.prototype.toggle = function() {
    var win = document.getElementById('omnichat-window');
    if (this.isOpen) {
      win.classList.remove('open');
      this.isOpen = false;
    } else {
      win.classList.add('open');
      this.isOpen = true;
      this.unreadCount = 0;
      this.updateBadge();
      this.scrollToBottom();
    }
  };

  WidgetUI.prototype.close = function() {
    document.getElementById('omnichat-window').classList.remove('open');
    this.isOpen = false;
  };

  WidgetUI.prototype.updateBadge = function() {
    var badge = document.getElementById('omnichat-badge');
    if (this.unreadCount > 0) {
      badge.textContent = this.unreadCount;
      badge.style.display = 'flex';
    } else {
      badge.style.display = 'none';
    }
  };

  WidgetUI.prototype.send = function() {
    var input = document.getElementById('omnichat-input');
    var text = input.value.trim();
    if (!text) return;
    input.value = '';

    var clientMsgId = generateUUID();
    var optMsg = {
      clientMessageId: clientMsgId,
      sender: 'visitor',
      senderName: 'شما',
      text: text,
      timestamp: formatTime()
    };
    this.appendMessage(optMsg);

    WidgetApi.sendMessage({
      text: text,
      clientMessageId: clientMsgId
    });
  };

  WidgetUI.prototype.renderMessages = function(msgs) {
    var list = document.getElementById('omnichat-msg-list');
    list.innerHTML = '';

    var welcome = document.createElement('div');
    welcome.className = 'omni-bubble operator';
    welcome.innerHTML = escapeHtml(Config.welcomeMessage) + '<div class="omni-time">' + formatTime() + '</div>';
    list.appendChild(welcome);

    var self = this;
    msgs.forEach(function(m) { self.appendMessage(m); });
    this.scrollToBottom();
  };

  WidgetUI.prototype.appendMessage = function(msg) {
    var list = document.getElementById('omnichat-msg-list');
    if (!list) return;

    var div = document.createElement('div');
    div.className = 'omni-bubble ' + (msg.sender === 'visitor' ? 'visitor' : 'operator');

    var bodyHtml = linkify(escapeHtml(msg.text || ''));
    if (msg.fileAttachment) {
      if (msg.fileAttachment.type === 'image') {
        bodyHtml += '<br><img src="' + escapeHtml(msg.fileAttachment.url) + '" style="max-width:100%; border-radius:8px; margin-top:6px;" />';
      } else {
        bodyHtml += '<br><a href="' + escapeHtml(msg.fileAttachment.url) + '" target="_blank" style="color:inherit; font-weight:bold;">📥 دانلود فایل</a>';
      }
    }

    div.innerHTML = bodyHtml + '<div class="omni-time">' + (msg.timestamp || formatTime(msg.createdAt)) + '</div>';
    list.appendChild(div);
    this.scrollToBottom();
  };

  WidgetUI.prototype.scrollToBottom = function() {
    var list = document.getElementById('omnichat-msg-list');
    if (list) list.scrollTop = list.scrollHeight;
  };

  window.OmniChat = {
    init: function(opts) {
      if (opts) {
        if (opts.endpoint) Config.endpoint = opts.endpoint.replace(/\/$/, '');
        if (opts.themeColor) Config.themeColor = opts.themeColor;
      }
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { new WidgetUI(); });
      } else {
        new WidgetUI();
      }
    }
  };

  // Auto init
  var script = document.currentScript;
  if (script) {
    var endpoint = script.getAttribute('data-endpoint') || '.';
    var themeColor = script.getAttribute('data-theme-color') || '#007AFF';
    window.OmniChat.init({ endpoint: endpoint, themeColor: themeColor });
  }

})(window, document);
